update_rule.pseudocode:
active = (policy.incentive_start_day <= day <= policy.incentive_end_day)
beneficiaries_today = 0
for each agent i:
  eligible_i = (income_i <= policy.eligibility_income_threshold)
  if active and eligible_i:
    if day - adoption_day_i >= policy.takeup_delay_days or adoption_day_i == -1:
      influence_i = min(1.0, policy.subsidy_amount / (policy.eligibility_income_threshold + 1e-9))
    else:
      influence_i = 0.0
    if not adopted_i and influence_i > 0:
      beneficiaries_today += 1
  else:
    influence_i = 0.0
emit policy.eligibility_flags, policy.influence_scalar_per_agent, policy.beneficiaries_daily
